      const checkboxes = Array.from(studiesPane.querySelectorAll('input[type="checkbox"][data-est-item]'));
      const targetCheckbox = checkboxes.find((cb)=> normalizeClinicalToken(cb.dataset.estItem || '') === normalizedStudy);
