        resumen_evolucion: normalizeConsentInputRaw(form.resumen_evolucion ?? altaState.form.resumen_evolucion ?? ''),
        diagnostico_final: normalizeConsentInputRaw(form.diagnostico_final ?? altaState.form.diagnostico_final ?? ''),
